-- Keep stable plan IDs so existing subscriptions and payment history remain valid.
UPDATE plans SET name='Standard', description='Protected playback for individual sites and smaller libraries.', entitlements=entitlements || '{"max_security_policy":"standard","secure_gateway":true,"dynamic_watermark":true,"device_control":true,"advanced_security":false,"security_event_retention_days":30,"audit_log_retention_days":30,"support_level":"standard"}'::jsonb, sort_order=10, badge=NULL, updated_at=now() WHERE id='starter';
UPDATE plans SET name='Strict', description='Stronger session and protected-segment controls for growing platforms.', entitlements=entitlements || '{"max_security_policy":"strict","secure_gateway":true,"dynamic_watermark":true,"device_control":true,"advanced_security":true,"security_event_retention_days":90,"audit_log_retention_days":90,"support_level":"priority"}'::jsonb, sort_order=20, badge='Recommended', updated_at=now() WHERE id='pro';
UPDATE plans SET name='Maximum', description='The highest policy ceiling and operational capacity for large platforms.', entitlements=entitlements || '{"max_security_policy":"maximum","secure_gateway":true,"dynamic_watermark":true,"device_control":true,"advanced_security":true,"security_event_retention_days":365,"audit_log_retention_days":365,"support_level":"priority"}'::jsonb, sort_order=30, badge='Strongest', updated_at=now() WHERE id='business';
